// Normalizes input from Chat Trigger, REST Webhook, or Manual Trigger
const item = $input.first()?.json || {};
const message = item.customerMessage || item.inputText || item.chatInput || item.body?.message || item.body?.prompt || item.message || item.text || "Hi, where is my order #INV-8842? My email is priya@shop.in";
const sessionId = item.sessionId || item.body?.sessionId || item.headers?.['x-session-id'] || ("sess-" + Math.random().toString(36).substring(2, 9));
const customerEmail = item.body?.email || item.email || "customer@example.com";
const channel = item.chatInput ? "chat" : (item.body ? "webhook" : "manual");

return [{
  json: {
    customerMessage: message,
    inputText: message,
    sessionId: sessionId,
    customerEmail: customerEmail,
    channel: channel,
    receivedAt: new Date().toISOString()
  }
}];

// Realistic enterprise order database lookup simulation
const orderId = (typeof query === 'string' ? query : JSON.stringify(query)).match(/INV-\d+|ORD-\d+/i)?.[0]?.toUpperCase() || 'INV-8842';

const mockDb = {
  'INV-8842': {
    status: 'Shipped - In Transit',
    carrier: 'BlueDart Express',
    trackingCode: 'BD-99201488',
    estimatedDelivery: 'Tomorrow by 4:00 PM',
    destination: 'Bengaluru, India',
    items: ['Ergonomic Wireless Keyboard', 'USB-C Fast Charger'],
    paidAmount: '$89.00'
  },
  'ORD-1029': {
    status: 'Processing in Warehouse',
    carrier: 'FedEx Priority',
    trackingCode: 'FDX-551982',
    estimatedDelivery: 'In 3 business days',
    destination: 'Mumbai, India',
    items: ['Noise Cancelling Headphones'],
    paidAmount: '$149.00'
  }
};

const record = mockDb[orderId] || {
  status: 'Order Found',
  carrier: 'Standard Delivery',
  trackingCode: 'STD-' + Math.floor(100000 + Math.random() * 900000),
  estimatedDelivery: 'Within 2-4 business days',
  items: ['Verified Purchased Item']
};

return JSON.stringify({
  orderId: orderId,
  ...record
});

